244. 	@Override
245. 	public <T> void scanCtType(CtType<T> type) {
246. 		if (child instanceof CtType && !(child instanceof CtTypeParameter)) {
247. 			if (type.getTypeMembers().contains(child)) {
248. 				type.removeTypeMember((CtType) child);
249. 			}
250. 			type.addNestedType((CtType<?>) child);
251. 			return;
252. 		} else if (child instanceof CtEnumValue && type instanceof CtEnum) {
253. 			((CtEnum) type).addEnumValue((CtEnumValue) child);
254. 		} else if (child instanceof CtField<?> field) {
255. 			// We add the field in addRecordComponent. Afterward, however, JDT visits the Field itself -> Duplication.
256. 			// To combat this, we delete the existing field and trust JDTs version.
257. 			if (type instanceof CtRecord record && !field.isStatic()) {
258. 				CtField<?> existing = record.getField(field.getSimpleName());
259. 				if (existing != null) {
260. 					record.removeField(existing);
261. 				}
262. 			}
263. 			type.addField(field);
264. 			return;
265. 		} else if (child instanceof CtConstructor) {
266. 			return;
267. 		}
268. 		if (child instanceof CtMethod) {
269. 			type.addMethod((CtMethod<?>) child);
270. 			return;
271. 		}
272. 		super.scanCtType(type);
273. 	}
