275. 	@Override
276. 	public <T> void scanCtVariable(CtVariable<T> v) {
277. 		if (childJDT instanceof TypeReference && child instanceof CtTypeAccess) {
278. 			v.setType(((CtTypeAccess) child).getAccessedType());
279. 			substituteAnnotation((CtTypedElement) v);
280. 			return;
281. 		} else if (child instanceof CtExpression && hasChildEqualsToDefaultValue(v)) {
282. 			v.setDefaultExpression((CtExpression<T>) child);
283. 			return;
284. 		}
285. 		super.scanCtVariable(v);
286. 	}
