288. 	private <T> boolean hasChildEqualsToDefaultValue(CtVariable<T> ctVariable) {
289. 		if (jdtTreeBuilder.getContextBuilder().getCurrentNode() instanceof AnnotationMethodDeclaration) {
290. 			final AnnotationMethodDeclaration parent = (AnnotationMethodDeclaration) jdtTreeBuilder.getContextBuilder().getCurrentNode();
291. 			// Default value is equals to the jdt child.
292. 			return parent.defaultValue != null && getFinalExpressionFromCast(parent.defaultValue).equals(childJDT)
293. 					// Return type not yet initialized.
294. 					&& !child.equals(ctVariable.getDefaultExpression());
295. 		}
296. 		final AbstractVariableDeclaration parent = (AbstractVariableDeclaration) jdtTreeBuilder.getContextBuilder().getCurrentNode();
297. 		// Default value is equals to the jdt child.
298. 		return parent.initialization != null && getFinalExpressionFromCast(parent.initialization).equals(childJDT)
299. 				// Return type not yet initialized.
300. 				&& !child.equals(ctVariable.getDefaultExpression());
301. 	}
