428. 	@Override
429. 	public <T> void visitCtBinaryOperator(CtBinaryOperator<T> operator) {
430. 		CtElement child = operator.getKind() == INSTANCEOF && operator.getLeftHandOperand() != null
431. 			? adjustIfLocalVariableToTypePattern(this.child)
432. 			: this.child;
433. 		if (child instanceof CtExpression) {
434. 			if (operator.getLeftHandOperand() == null) {
435. 				operator.setLeftHandOperand((CtExpression<?>) child);
436. 				return;
437. 			} else if (operator.getRightHandOperand() == null) {
438. 				if (child.getPosition().isValidPosition()) {
439. 					int childEnd = child.getPosition().getSourceEnd();
440. 					SourcePosition oldPos = operator.getPosition();
441. 					if (oldPos.isValidPosition() && oldPos.getSourceEnd() < childEnd) {
442. 						//fix parent position if right hand expression is `x instanceof List<?>` which has bad sourceEnd ending before `<?>
443. 						int[] lineSeparatorPositions = jdtTreeBuilder.getContextBuilder().getCompilationUnitLineSeparatorPositions();
444. 						operator.setPosition(operator.getFactory().Core().createSourcePosition(
445. 								oldPos.getCompilationUnit(),
446. 								oldPos.getSourceStart(), childEnd,
447. 								lineSeparatorPositions));
448. 					}
449. 				}
450. 				operator.setRightHandOperand((CtExpression<?>) child);
451. 				return;
452. 			} else if (jdtTreeBuilder.getContextBuilder().getCurrentNode() instanceof StringLiteralConcatenation) {
453. 				CtBinaryOperator<?> op = operator.getFactory().Core().createBinaryOperator();
454. 				op.setKind(BinaryOperatorKind.PLUS);
455. 				op.setLeftHandOperand(operator.getLeftHandOperand());
456. 				op.setRightHandOperand(operator.getRightHandOperand());
457. 				op.setType(operator.getFactory().Type().stringType());
458. 				operator.setLeftHandOperand(op);
459. 				operator.setRightHandOperand(((CtExpression<?>) child));
460. 				int[] lineSeparatorPositions = jdtTreeBuilder.getContextBuilder().getCompilationUnitLineSeparatorPositions();
461. 				SourcePosition leftPosition = op.getLeftHandOperand().getPosition();
462. 				SourcePosition rightPosition = op.getRightHandOperand().getPosition();
463. 				op.setPosition(op.getFactory().createSourcePosition(leftPosition.getCompilationUnit(), leftPosition.getSourceStart(), rightPosition.getSourceEnd(), lineSeparatorPositions));
464. 				return;
465. 			}
466. 		}
467. 		super.visitCtBinaryOperator(operator);
468. 	}
