470. 	/**
471. 	 * {@return the original element if it is not a local variable, a type pattern containing the local variable otherwise}
472. 	 *
473. 	 * @param original the original element
474. 	 */
475. 	private CtElement adjustIfLocalVariableToTypePattern(CtElement original) {
476. 		CtElement child = original;
477. 		// check if this is a type pattern, as it needs special treatment
478. 		// patterns are only allowed for instanceof and on the right hand
479. 		if (child instanceof CtLocalVariable) {
480. 			CtTypePattern typePattern = child.getFactory().Core().createTypePattern();
481. 			typePattern.setVariable((CtLocalVariable<?>) child);
482. 			// as we create the type pattern just here, we need to set its source position - which is luckily the same
483. 			typePattern.setPosition(child.getPosition());
484. 			child = typePattern; // replace the local variable with a pattern (which is a CtExpression)
485. 		}
486. 		return child;
487. 	}
