503. 	@Override
504. 	public <E> void visitCtCase(CtCase<E> caseStatement) {
505. 		final ASTNode node = jdtTreeBuilder.getContextBuilder().getCurrentNode();
506. 		if (node instanceof CaseStatement) {
507. 			caseStatement.setCaseKind(((CaseStatement) node).isExpr ? CaseKind.ARROW : CaseKind.COLON);
508. 		}
509. 		if (shouldAddAsCaseExpression(caseStatement, node)) {
510. 			if (child instanceof CtPattern pattern) {
511. 				caseStatement.addCaseExpression((CtExpression<E>) jdtTreeBuilder.getFactory().Core().createCasePattern().setPattern(pattern));
512. 			} else {
513. 				caseStatement.addCaseExpression((CtExpression<E>) child);
514. 			}
515. 			return;
516. 		} else if (child instanceof CtStatement) {
517. 			caseStatement.addStatement((CtStatement) child);
518. 			return;
519. 		} else if (child instanceof CtExpression<?> guard) {
520. 			caseStatement.setGuard(guard);
521. 		}
522. 		super.visitCtCase(caseStatement);
523. 	}
524. 
525. 	private <E> boolean shouldAddAsCaseExpression(CtCase<E> caseStatement, ASTNode node) {
526. 		if (!(node instanceof CaseStatement cs)) {
527. 			return false;
528. 		}
529. 		if (cs.constantExpressions == null) {
530. 			return false;
531. 		}
532. 		if (child instanceof CtExpression
533. 			&& caseStatement.getCaseExpressions().size() < cs.constantExpressions.length) {
534. 			return true;
535. 		}
536. 		// case A _, B _ -> {} is only one constantExpression in JDT, but an EitherOrMultiPattern
537. 		// so we need to unpack it and see how many case expressions it actually is
538. 		if (cs.constantExpressions.length == 1 && cs.constantExpressions[0] instanceof EitherOrMultiPattern eomp) {
539. 			// returns true if we still expect more case expressions to be added
540. 			return caseStatement.getCaseExpressions().size() < eomp.getAlternatives().length;
541. 		}
542. 		return false;
543. 	}
