545. 	@Override
546. 	public void visitCtCatch(CtCatch catchBlock) {
547. 		if (child instanceof CtBlock) {
548. 			catchBlock.setBody((CtBlock<?>) child);
549. 			return;
550. 		} else if (child instanceof CtCatchVariable) {
551. 			catchBlock.setParameter((CtCatchVariable<? extends Throwable>) child);
552. 			// Catch annotations are processed before actual CtCatchVariable is created and because of that they attach to CtCatch.
553. 			// Since annotations cannot be attached to CtCatch itself, we can simply transfer them to CtCatchVariable.
554. 			catchBlock.getAnnotations().forEach(a -> { a.setParent(child); child.addAnnotation(a); });
555. 			catchBlock.setAnnotations(List.of());
556. 			return;
557. 		}
558. 		super.visitCtCatch(catchBlock);
559. 	}
