591. 	private <T> void fixJdtEnumConstructorSuperCall(CtClass<T> ctClass, CtConstructor<T> constructor) {
592. 		// For some reason JDT inserts a `super()` call in implicit enum constructors.
593. 		// Explicit super calls are forbidden as java.lang.Enum subclasses are permitted by the JLS to delegate
594. 		// to the Enum constructor in whatever way they like.
595. 		// The constructor is implicit so this isn't *technically* illegal, but it doesn't really make much sense
596. 		// as explicit constructors can never contain such a call. Additionally, the Enum class from the standard
597. 		// library has a "String, int" constructor, rendering the parameterless supercall semantically invalid.
598. 		// We just remove the call to make it a bit more consistent.
599. 		// See https://github.com/INRIA/spoon/issues/4758 for more details.
600. 		if (!child.isImplicit() || !ctClass.isEnum() || !constructor.getParameters().isEmpty()) {
601. 			return;
602. 		}
603. 		if (constructor.getBody().getStatements().isEmpty()) {
604. 			return;
605. 		}
606. 		if (!(constructor.getBody().getStatement(0) instanceof CtInvocation)) {
607. 			return;
608. 		}
609. 
610. 		CtInvocation<?> superCall = constructor.getBody().getStatement(0);
611. 		if (superCall.getExecutable().getSimpleName().equals("<init>")) {
612. 			constructor.getBody().removeStatement(superCall);
613. 		}
614. 	}
