617. 	public void visitCtTypeParameter(CtTypeParameter typeParameter) {
618. 		if (childJDT instanceof TypeReference && child instanceof CtTypeAccess) {
619. 			if (typeParameter.getSuperclass() == null) {
620. 				typeParameter.setSuperclass(((CtTypeAccess) child).getAccessedType());
621. 			} else if (typeParameter.getSuperclass() instanceof CtIntersectionTypeReference) {
622. 				typeParameter.getSuperclass().asCtIntersectionTypeReference().addBound(((CtTypeAccess) child).getAccessedType());
623. 			} else {
624. 				final List<CtTypeReference<?>> refs = new ArrayList<>();
625. 				refs.add(typeParameter.getSuperclass());
626. 				refs.add(((CtTypeAccess) child).getAccessedType());
627. 				typeParameter.setSuperclass(jdtTreeBuilder.getFactory().Type().createIntersectionTypeReferenceWithBounds(refs));
628. 			}
629. 			return;
630. 		}
631. 		super.visitCtTypeParameter(typeParameter);
632. 	}
