634. 	@Override
635. 	public <T> void visitCtConditional(CtConditional<T> conditional) {
636. 		if (child instanceof CtExpression) {
637. 			if (conditional.getCondition() == null) {
638. 				conditional.setCondition((CtExpression<Boolean>) child);
