798. 	private <T> boolean setTargetFromUnqualifiedAccess(CtInvocation<T> invocation) {
799. 		// A call to a statically imported method (e.g. assertTrue(false)) is modelled as
800. 		// "this.assertTrue(false)" by JDT. We need to unscramble that heuristically and replace the
801. 		// "this" reference with the correct type (e.g. org.junit.api.Assertions)
802. 
803. 		// Additionally, references to methods of enclosing classes are also modelled as "this" by JDT.
804. 		// Compare with Test "correctlySetsThisTargetForUnqualifiedCalls".
805. 
806. 		// We need a MessageSend as the parent to resolve the actualType from the receiver
807. 		if (!(parentPair.node() instanceof MessageSend messageSend)) {
808. 			return false;
809. 		}
810. 		if (messageSend.actualReceiverType == null || messageSend.receiver.resolvedType == null) {
811. 			return false;
812. 		}
813. 
814. 		ReferenceBuilder referenceBuilder = jdtTreeBuilder.getReferencesBuilder();
815. 		CtTypeReference<?> actualReceiverType = referenceBuilder.getTypeReference(messageSend.actualReceiverType);
816. 		CtTypeReference<?> resolvedReceiverType = referenceBuilder.getTypeReference(messageSend.receiver.resolvedType);
817. 
818. 		// If they match we have a normal "this" reference
819. 		if (actualReceiverType.equals(resolvedReceiverType)) {
820. 			return false;
821. 		}
822. 
823. 		if (messageSend.binding() == null || !messageSend.binding().isStatic()) {
824. 			// Emulate outer this access
825. 			while (resolvedReceiverType != null) {
826. 				resolvedReceiverType = resolvedReceiverType.getDeclaringType();
827. 				if (actualReceiverType.equals(resolvedReceiverType)) {
828. 					invocation.setTarget(jdtTreeBuilder.getFactory().Code().createThisAccess(actualReceiverType, true));
829. 					return true;
830. 				}
831. 			}
832. 			// I don't think this can happen but let's be conservative and preserve the previous behaviour
833. 			return false;
834. 		}
835. 
836. 		// If not, we probably had a static import/static outer method reference here and should use the actual type
837. 		// instead
838. 		invocation.setTarget(jdtTreeBuilder.getFactory().Code().createTypeAccess(actualReceiverType, true));
839. 		return true;
840. 	}
