1175. 			// JDTTreeBuilder#visit(SingleTypeReference wraps the child in a CtTypeAccess later on,
1176. 			// replacing its parent. Therefore, we need to use a clone for this otherwise the typeReference
1177. 			// has two different parents (one wins and the model is inconsistent).
1178. 			pattern.setRecordType(typeReference.clone());
1179. 		} else if (child instanceof CtPattern innerPattern) {
1180. 			pattern.addPattern(innerPattern);
1181. 		}
1182. 	}
1183. 
1184. 	/**
1185. 	 * Modifies the set of constructors of a {@link CtRecord} instance based on the properties of a new constructor.
1186. 	 * <p>
1187. 	 * This method performs the following operations:
1188. 	 * <p>
1189. 	 * - If the new constructor is implicit, the method checks against all constructors in the record. If a constructor
1190. 	 * with matching parameters is found, the function returns without adding the new constructor.
1191. 	 * <p>
1192. 	 * - If the new constructor is not implicit, the method traverses the existing constructors of the record. If any
1193. 	 * implicit constructor with matching parameters is found, it's removed from the record.
1194. 	 * <p>
1195. 	 * - If constructor to be added passes the conditions above, or no matching parameters are found, it gets added to the record.
1196. 	 *
1197. 	 * @param recordType     The {@link CtRecord} instance to which the new constructor might be added.
1198. 	 * @param newConstructor The new constructor that should be added to the record, contingent on certain conditions.
1199. 	 */
1200. 	private static void adjustConstructors(CtRecord recordType, CtConstructor<Object> newConstructor) {
1201. 		if (newConstructor.isImplicit()) {
1202. 			for (CtConstructor<Object> constructor : recordType.getConstructors()) {
1203. 				if (hasSameParameters(newConstructor, constructor)) {
1204. 					return;
1205. 				}
1206. 			}
1207. 		} else {
1208. 			for (CtConstructor<Object> constructor : recordType.getConstructors()) {
1209. 				if (constructor.isImplicit() && hasSameParameters(newConstructor, constructor)) {
1210. 					recordType.removeConstructor(constructor);
1211. 				}
1212. 			}
1213. 		}
1214. 		recordType.addConstructor(newConstructor);
1215. 	}
1216. 
1217. 	private static boolean hasSameParameters(CtConstructor<Object> newConstructor, CtConstructor<Object> constructor) {
1218. 		// use endsWith because constructor already has a declaring type set while newConstructor doesn't
1219. 		// but we are only interested in the parameters, so we compare e.g. "R(int)" with "(int)"
1220. 		return constructor.getSignature().endsWith(newConstructor.getSignature());
1221. 	}
1222. 
1223. 	@Override
1224. 	public void visitCtRecordComponent(CtRecordComponent recordComponent) {
1225. 		if (childJDT instanceof TypeReference && child instanceof CtTypeAccess) {
1226. 			recordComponent.setType(((CtTypeAccess) child).getAccessedType());
1227. 			substituteAnnotation((CtTypedElement) recordComponent);
1228. 			return;
1229. 		}
1230. 		scanCtElement(recordComponent);
1231. 	}
1232. }
