247. 	private LiteralBase getBase(NumberLiteral numberLiteral) {
248. 		String sourceString = new String(numberLiteral.source());
249. 
250. 		if (sourceString.startsWith("0x") || sourceString.startsWith("0X")) {
251. 			return LiteralBase.HEXADECIMAL;
252. 		}
253. 
254. 		if (sourceString.startsWith("0b") || sourceString.startsWith("0B")) {
255. 			return LiteralBase.BINARY;
256. 		}
257. 
258. 		if (sourceString.startsWith("0")) {
259. 			if ((numberLiteral instanceof IntLiteral && sourceString.length() > 1)
260. 				|| (numberLiteral instanceof LongLiteral && sourceString.length() > 2)) {
261. 				return LiteralBase.OCTAL;
262. 			}
263. 		}
264. 
265. 		return LiteralBase.DECIMAL;
266. 	}
