1165. 		}
1166. 		if (constructorDeclaration.binding != null) {
1167. 			c.setExtendedModifiers(getModifiers(constructorDeclaration.binding.modifiers, true, ModifierTarget.CONSTRUCTOR));
1168. 		}
1169. 		// avoid to add explicit modifier to implicit constructor
1170. 		if (!c.isImplicit()) {
1171. 			for (CtExtendedModifier extendedModifier : getModifiers(constructorDeclaration.modifiers, false, ModifierTarget.CONSTRUCTOR)) {
1172. 				c.addModifier(extendedModifier.getKind()); // avoid to keep implicit AND explicit modifier of the same kind.
