1453. 		// No explicit type arguments given for call, but JDT inferred them (e.g. in a List.of("foo") call)
1454. 		if (messageSend.binding instanceof ParameterizedGenericMethodBinding && messageSend.typeArguments == null) {
1455. 			ParameterizedGenericMethodBinding binding = (ParameterizedGenericMethodBinding) messageSend.binding;
1456. 			for (TypeBinding argument : binding.typeArguments) {
1457. 				CtTypeReference<Object> reference = getReferencesBuilder().getTypeReference(argument);
1458. 				reference.setImplicit(true);
1459. 				inv.addActualTypeArgument(reference);
1460. 			}
1461. 		}
1462. 		context.enter(inv, messageSend);
1463. 		return true;
1464. 	}
