import spoon.Launcher;
import spoon.reflect.CtModel;
import spoon.reflect.code.CtLocalVariable;
import spoon.reflect.visitor.filter.TypeFilter;

public class ParseCode {
    public static void main(String[] args) {
        Launcher launcher = new Launcher();
        launcher.getEnvironment().setComplianceLevel(21);
        launcher.getEnvironment().setNoClasspath(true);
        launcher.addInputResource(new spoon.support.compiler.VirtualFile(
            "class A { public void f(int i) { int x = switch(i) { case 1 -> 10; case 2 -> 20; default -> 30; }; } }"
        ));
        CtModel model = launcher.buildModel();
        CtLocalVariable<?> localVariable = model.getElements(new TypeFilter<>(CtLocalVariable.class)).get(0);
        System.out.println("Assignment class: " + localVariable.getAssignment().getClass().getName());
        System.out.println("Assignment: " + localVariable.getAssignment());
    }
}

