43. 
44. import java.util.ArrayDeque;
45. import java.util.ArrayList;
46. import java.util.Deque;
47. import java.util.EnumSet;
48. import java.util.List;
49. 
50. import static java.lang.String.format;
51. import static spoon.reflect.ModelElementContainerDefaultCapacities.CASTS_CONTAINER_DEFAULT_CAPACITY;
52. 
53. @Internal
54. public class ContextBuilder {
55. 
56. 	Deque<String> annotationValueName = new ArrayDeque<>();
57. 
58. 	public static class CastInfo {
59. 		int nrOfBrackets;
60. 		CtTypeReference<?> typeRef;
61. 	}
62. 
63. 	List<CastInfo> casts = new ArrayList<>(CASTS_CONTAINER_DEFAULT_CAPACITY);
64. 
65. 	CompilationUnitDeclaration compilationunitdeclaration;
66. 
67. 	CompilationUnit compilationUnitSpoon;
68. 
69. 	boolean isBuildLambda;
70. 
71. 	boolean isBuildTypeCast;
72. 
73. 	boolean ignoreComputeImports;
74. 
75. 	/**
76. 	 * Stack of all parents elements
77. 	 */
78. 	private final Deque<ASTPair> stack = new ArrayDeque<>();
79. 
80. 	private final JDTTreeBuilder jdtTreeBuilder;
81. 
82. 	ContextBuilder(JDTTreeBuilder jdtTreeBuilder) {
83. 		this.jdtTreeBuilder = jdtTreeBuilder;
84. 	}
85. 
86. 	@SuppressWarnings("unchecked")
87. 	void enter(CtElement e, ASTNode node) {
88. 		stack.push(new ASTPair(e, node));
89. 		if (!(e instanceof CtPackage) || (compilationUnitSpoon.getFile() != null && compilationUnitSpoon.getFile().getName().equals(DefaultJavaPrettyPrinter.JAVA_PACKAGE_DECLARATION))) {
90. 			if (compilationunitdeclaration != null && !e.isImplicit()) {
91. 				try {
92. 					e.setPosition(this.jdtTreeBuilder.getPositionBuilder().buildPositionCtElement(e, node));
93. 				} catch (Exception ex) {
94. 					e.setPosition(SourcePosition.NOPOSITION);
95. 				}
96. 			}
97. 		}
98. 
99. 		ASTPair pair = stack.peek();
100. 		CtElement current = pair.element();
101. 
102. 		if (current instanceof CtExpression) {
103. 			while (!casts.isEmpty()) {
104. 				((CtExpression<?>) current).addTypeCast(casts.remove(0).typeRef);
105. 			}
106. 		}
107. 
108. 		try {
109. 			if (e instanceof CtTypedElement && !(e instanceof CtConstructorCall) && !(e instanceof CtCatchVariable) && node instanceof Expression) {
110. 				if (((CtTypedElement<?>) e).getType() == null) {
111. 					((CtTypedElement<Object>) e).setType(this.jdtTreeBuilder.getReferencesBuilder().getTypeReference(((Expression) node).resolvedType));
112. 				}
113. 			}
114. 		} catch (UnsupportedOperationException ignore) {
115. 			// For some element, we throw an UnsupportedOperationException when we call setType().
116. 		}
117. 	}
118. 
119. 	void exit(ASTNode node) {
120. 		ASTPair pair = stack.pop();
121. 		if (pair.node() != node) {
122. 			throw new RuntimeException("Inconsistent Stack " + node + "\n" + pair.node());
123. 		}
124. 		CtElement current = pair.element();
125. 		if (!stack.isEmpty()) {
126. 			this.jdtTreeBuilder.getExiter().setChild(current);
127. 			this.jdtTreeBuilder.getExiter().setChild(pair.node());
128. 			ASTPair parentPair = stack.peek();
129. 			this.jdtTreeBuilder.getExiter().exitParent(parentPair);
130. 		}
131. 	}
132. 
133. 	/**
134. 	 * @return all {@link ASTPair}s currently on the stack
135. 	 */
136. 	Iterable<ASTPair> getAllContexts() {
137. 		return stack;
138. 	}
139. 
140. 	/**
141. 	 * @return {@code true} if there are any elements on the stack
142. 	 */
143. 	boolean hasCurrentContext() {
144. 		return !stack.isEmpty();
145. 	}
146. 
147. 	/**
148. 	 *
149. 	 * @return the {@link CtElement} on the top of the stack
150. 	 * @throws NullPointerException if the stack is empty
151. 	 */
152. 	CtElement getCurrentElement() {
153. 		return stack.peek().element();
154. 	}
155. 
156. 	/**
157. 	 * @return the {@link ASTNode} on the top of the stack
158. 	 * @throws NullPointerException if the stack is empty
159. 	 */
160. 	ASTNode getCurrentNode() {
161. 		return stack.peek().node();
162. 	}
163. 
164. 	CtElement getContextElementOnLevel(int level) {
165. 		for (ASTPair pair : stack) {
166. 			if (level == 0) {
167. 				return pair.element();
168. 			}
169. 			level--;
170. 		}
171. 		return null;
172. 	}
173. 
174. 	<T extends CtElement> T getParentElementOfType(Class<T> clazz) {
175. 		for (ASTPair pair : stack) {
176. 			if (clazz.isInstance(pair.element())) {
177. 				return (T) pair.element();
178. 			}
179. 		}
180. 		return null;
181. 	}
182. 
183. 	ASTPair getParentContextOfType(Class<? extends CtElement> clazz) {
184. 		for (ASTPair pair : stack) {
185. 			if (clazz.isInstance(pair.element())) {
186. 				return pair;
187. 			}
188. 		}
189. 		return null;
190. 	}
191. 
192. 	@SuppressWarnings("unchecked")
193. 	<T> CtLocalVariable<T> getLocalVariableDeclaration(final String name) {
194. 		final Class<CtLocalVariable<T>> clazz = (Class<CtLocalVariable<T>>)
195. 				jdtTreeBuilder.getFactory().Core().createLocalVariable().getClass();
196. 		final CtLocalVariable<T> localVariable =
197. 				this.<T, CtLocalVariable<T>>getVariableDeclaration(name, clazz);
198. 		if (localVariable == null) {
199. 			// note: this happens when using the new try(vardelc) structure
200. 			this.jdtTreeBuilder.getLogger().error(
201. 					format("Could not find declaration for local variable %s at %s",
202. 							name, getCurrentElement().getPosition()));
203. 		}
204. 		return localVariable;
205. 	}
206. 
207. 	@SuppressWarnings("unchecked")
208. 	<T> CtCatchVariable<T> getCatchVariableDeclaration(final String name) {
209. 		final Class<CtCatchVariable<T>> clazz = (Class<CtCatchVariable<T>>)
210. 				jdtTreeBuilder.getFactory().Core().createCatchVariable().getClass();
211. 		final CtCatchVariable<T> catchVariable =
212. 				this.<T, CtCatchVariable<T>>getVariableDeclaration(name, clazz);
213. 		if (catchVariable == null) {
214. 			// note: this happens when using the new try(vardelc) structure
215. 			this.jdtTreeBuilder.getLogger().error(
216. 					format("Could not find declaration for catch variable %s at %s",
217. 							name, getCurrentElement().getPosition()));
218. 		}
219. 		return catchVariable;
220. 	}
221. 
222. 	<T> CtVariable<T> getVariableDeclaration(final String name) {
223. 		final CtVariable<T> variable = this.<T, CtVariable<T>>getVariableDeclaration(name, null);
224. 		if (variable == null) {
225. 			// note: this happens when using the new try(vardelc) structure
226. 			// note: this can happen when identifier is not a variable name but e.g. a Type name.
227. 			this.jdtTreeBuilder.getLogger().debug(
228. 					format("Could not find declaration for variable %s at %s.",
229. 							name, getCurrentElement().getPosition()));
230. 		}
231. 		return variable;
232. 	}
233. 
234. 	/**
235. 	 * Returns qualified name with appropriate package separator and inner type separator
236. 	 */
237. 	private static String getNormalQualifiedName(ReferenceBinding referenceBinding) {
238. 		String pkg = new String(referenceBinding.getPackage().readableName()).replaceAll("\\.", "\\" + CtPackage.PACKAGE_SEPARATOR);
239. 		String name = new String(referenceBinding.qualifiedSourceName()).replaceAll("\\.", "\\" + CtType.INNERTTYPE_SEPARATOR);
240. 		return pkg.isEmpty() ? name : pkg + "." + name;
241. 	}
242. 
243. 	@SuppressWarnings("unchecked")
244. 	private <T, U extends CtVariable<T>> U getVariableDeclaration(
245. 			final String name, final Class<U> clazz) {
246. 		final CoreFactory coreFactory = jdtTreeBuilder.getFactory().Core();
247. 		final TypeFactory typeFactory = jdtTreeBuilder.getFactory().Type();
248. 		final ClassFactory classFactory = jdtTreeBuilder.getFactory().Class();
249. 		final InterfaceFactory interfaceFactory = jdtTreeBuilder.getFactory().Interface();
250. 		final FieldFactory fieldFactory = jdtTreeBuilder.getFactory().Field();
251. 		final ReferenceBuilder referenceBuilder = jdtTreeBuilder.getReferencesBuilder();
252. 		final Environment environment = jdtTreeBuilder.getFactory().getEnvironment();
253. 		// there is some extra work to do if we are looking for CtFields (and subclasses)
254. 		final boolean lookingForFields = clazz == null
255. 				|| coreFactory.createField().getClass().isAssignableFrom(clazz);
256. 
257. 		// try to find the variable on stack beginning with the most recent element
258. 		for (final ASTPair astPair : stack) {
259. 			// the variable may have been declared directly by one of these elements
260. 			final ScopeRespectingVariableScanner<U> scanner =
261. 					new ScopeRespectingVariableScanner(name, clazz);
262. 			astPair.element().accept(scanner);
263. 			if (scanner.getResult() != null) {
264. 				return scanner.getResult();
265. 			}
266. 
267. 			// the variable may have been declared in a super class/interface
268. 			if (lookingForFields && astPair.node() instanceof TypeDeclaration nodeDeclaration) {
269. 				final Deque<ReferenceBinding> referenceBindings = new ArrayDeque<>();
270. 				// add super class if any
271. 				if (nodeDeclaration.superclass != null
272. 						&& nodeDeclaration.superclass.resolvedType instanceof ReferenceBinding) {
273. 					referenceBindings.push((ReferenceBinding) nodeDeclaration.superclass.resolvedType);
274. 				}
275. 				// add interfaces if any
276. 				if (nodeDeclaration.superInterfaces != null) {
277. 					for (final TypeReference tr : nodeDeclaration.superInterfaces) {
278. 						if (tr.resolvedType instanceof ReferenceBinding) {
279. 							referenceBindings.push((ReferenceBinding) tr.resolvedType);
280. 						}
281. 					}
282. 				}
283. 
284. 				while (!referenceBindings.isEmpty()) {
285. 					final ReferenceBinding referenceBinding = referenceBindings.pop();
286. 					for (final FieldBinding fieldBinding : referenceBinding.fields()) {
287. 						if (name.equals(new String(fieldBinding.readableName()))) {
288. 							final String qualifiedNameOfParent = getNormalQualifiedName(referenceBinding);
289. 
290. 							CtType<?> parentOfField = typeFactory.get(qualifiedNameOfParent);
291. 							if (parentOfField != null) {
292. 								return (U) parentOfField.getField(name);
293. 							}
294. 							parentOfField = referenceBinding.isClass()
295. 									? classFactory.create(qualifiedNameOfParent)
296. 									: interfaceFactory.create(qualifiedNameOfParent);
297. 
298. 							U field = (U) fieldFactory.create(parentOfField,
299. 									EnumSet.noneOf(ModifierKind.class),
300. 									referenceBuilder.getTypeReference(fieldBinding.type),
301. 									name);
302. 							return field.setExtendedModifiers(JDTTreeBuilderQuery.getModifiers(fieldBinding.modifiers, true, ModifierTarget.FIELD));
303. 						}
304. 					}
305. 					// add super class if any
306. 					final ReferenceBinding superclass = referenceBinding.superclass();
307. 					if (superclass != null) {
308. 						referenceBindings.push(superclass);
309. 					}
310. 					// add interfaces if any
311. 					final ReferenceBinding[] interfaces = referenceBinding.superInterfaces();
312. 					if (interfaces != null) {
313. 						for (ReferenceBinding rb : interfaces) {
314. 							referenceBindings.push(rb);
315. 						}
316. 					}
317. 				}
318. 			}
319. 		}
320. 
321. 		// the variable may have been imported statically from another class/interface
322. 		if (lookingForFields) {
323. 			final CtReference potentialReferenceToField =
324. 					referenceBuilder.getDeclaringReferenceFromImports(name.toCharArray());
325. 			if (potentialReferenceToField instanceof CtTypeReference) {
326. 				final CtTypeReference typeReference = (CtTypeReference) potentialReferenceToField;
327. 				try {
328. 					final Class classOfType = typeReference.getActualClass();
329. 					if (classOfType != null) {
330. 						final CtType declaringTypeOfField = typeReference.isInterface()
331. 								? interfaceFactory.get(classOfType) : classFactory.get(classOfType);
332. 						final CtField field = declaringTypeOfField.getField(name);
333. 						if (field != null) {
334. 							return (U) field;
335. 						}
336. 					}
337. 				} catch (final SpoonClassNotFoundException scnfe) {
338. 					// in noclasspath mode we do some heuristics to determine if `name` could be a
339. 					// field that has been imported statically from another class (or interface).
340. 					if (environment.getNoClasspath()) {
341. 						// if `potentialReferenceToField` is a `CtTypeReference` then `name` must
342. 						// have been imported statically. Otherwise, `potentialReferenceToField`
343. 						// would be a CtPackageReference!
344. 
345. 						// if `name` consists only of upper case characters separated by '_', we
346. 						// assume a constant value according to JLS.
347. 						if (name.toUpperCase().equals(name)) {
348. 							final CtType parentOfField =
349. 									classFactory.create(typeReference.getQualifiedName());
350. 							// it is the best thing we can do
351. 							final CtField field = coreFactory.createField();
352. 							field.setParent(parentOfField);
353. 							field.setSimpleName(name);
354. 							// it is the best thing we can do
355. 							field.setType(typeFactory.nullType());
356. 							return (U) field;
357. 						}
358. 					}
359. 				}
360. 			}
361. 		}
362. 
363. 		return null;
364. 	}
365. 
366. 	/**
367. 	 * An {@link EarlyTerminatingScanner} that is supposed to find a {@link CtVariable} with
368. 	 * specific name respecting the current scope given by {@link ContextBuilder#stack}.
369. 
370. 	 * @param <T> The actual type of the {@link CtVariable} we are looking for. Examples include
371. 	 *            {@link CtLocalVariable}, {@link CtField}, and so on.
372. 	 */
373. 	private class ScopeRespectingVariableScanner<T extends CtVariable>
374. 			extends EarlyTerminatingScanner<T> {
375. 
376. 		/**
377. 		 * The class object of {@link T} that is required to filter particular elements in
378. 		 * {@link #scan(CtElement)}.
379. 		 */
380. 		private final Class<T> clazz;
381. 
382. 		/**
383. 		 * The name of the variable we are looking for ({@link CtVariable#getSimpleName()}).
384. 		 */
385. 		final String name;
386. 
387. 		/**
388. 		 * Creates a new {@link EarlyTerminatingScanner} that tries to find a {@link CtVariable}
389. 		 * with name {@code pName} (using {@link CtVariable#getSimpleName()}) and upper type bound
390. 		 * {@code pType}.
391. 		 *
392. 		 * @param pName	The name of the variable we are looking for.
393. 		 * @param pType	{@link T}'s class object ({@link Object#getClass()}). {@link null} values
394. 		 *              are permitted and indicate that we are looking for any subclass of
395. 		 *              {@link CtVariable} (including {@link CtVariable} itself).
396. 		 */
397. 		ScopeRespectingVariableScanner(final String pName, final Class<T> pType) {
398. 			clazz =  (Class<T>) (pType == null ? CtVariable.class : pType);
399. 			name = pName;
400. 		}
401. 
402. 		@Override
403. 		public void scan(final CtElement element) {
404. 			if (element != null && clazz.isAssignableFrom(element.getClass())) {
405. 				final T potentialVariable = (T) element;
406. 				if (name.equals(potentialVariable.getSimpleName())) {
407. 					// Since the AST is not completely available yet, we can not check if element's
408. 					// parent (ep) contains the innermost element of `stack` (ie). Therefore, we
409. 					// have to check if one of the following condition holds:
410. 					//
411. 					//    1) Does `stack` contain `ep`?
412. 					//    2) Is `ep` the body of one of `stack`'s CtExecutable elements?
413. 					//
414. 					// The first condition is easy to see. If `stack` contains `ep` then `ep` and
415. 					// all it's declared variables are in scope of `ie`. Unfortunately, there is a
416. 					// special case in which a variable (a CtLocalVariable) has been declared in a
417. 					// block (CtBlock) of, for instance, a method. Such a block is not contained in
418. 					// `stack`. This peculiarity calls for the second condition.
419. 					final CtElement parentOfPotentialVariable = potentialVariable.getParent();
420. 					for (final ASTPair astPair : stack) {
421. 						if (astPair.element() == parentOfPotentialVariable) {
422. 							finish(potentialVariable);
423. 							return;
424. 						} else if (astPair.element() instanceof CtExecutable<?> executable) {
425. 							if (executable.getBody() == parentOfPotentialVariable) {
426. 								finish(potentialVariable);
427. 								return;
428. 							}
429. 						}
430. 					}
431. 				}
432. 			}
433. 			super.scan(element);
434. 		}
435. 
436. 		private void finish(final  T element) {
437. 			setResult(element);
438. 			terminate();
439. 		}
440. 	}
441. 
442. 	/**
443. 	 * @return line separator positions of actually processed compilation unit
444. 	 */
445. 	public int[] getCompilationUnitLineSeparatorPositions() {
446. 		return compilationunitdeclaration.compilationResult.lineSeparatorPositions;
447. 	}
448. 
449. 	/**
450. 	 * @return char content of actually processed compilation unit
451. 	 */
452. 	public char[] getCompilationUnitContents() {
453. 		return compilationunitdeclaration.compilationResult.compilationUnit.getContents();
454. 	}
455. }
