 				} catch (Exception ex) {
 					e.setPosition(SourcePosition.NOPOSITION);
 				}
 			}
 		}

 		ASTPair pair = stack.peek();
 		CtElement current = pair.element();

 		if (current instanceof CtExpression) {
 			while (!casts.isEmpty()) {
 				((CtExpression<?>) current).addTypeCast(casts.remove(0).typeRef);
 			}
 		}

