466. 	@Override
467. 	public void endVisit(LabeledStatement labeledStatement, BlockScope scope) {
468. 		CtBlock<?> block = (CtBlock<?>) context.getCurrentElement();
469. 		if (block.getStatements().size() == 1) {
470. 			CtStatement childStmt = block.getStatement(0);
471. 			if (childStmt.getLabel() == null) {
472. 				//the child statement has no label, so we can move label from `block` to child statement and to remove this `block`
473. 				//example code:
474. 				//label: while(true);
475. 				childStmt.setLabel(block.getLabel());
476. 				SourcePosition oldPos = childStmt.getPosition();
477. 				int newSourceStart = Math.min(oldPos.getSourceStart(), block.getPosition().getSourceStart());
478. 				if (newSourceStart != oldPos.getSourceStart()) {
479. 					childStmt.setPosition(block.getFactory().Core().createSourcePosition(
480. 							oldPos.getCompilationUnit(),
481. 							newSourceStart, oldPos.getSourceEnd(),
482. 							oldPos.getCompilationUnit().getLineSeparatorPositions()));
483. 				}
484. 				//call exit with origin labeled statement
485. 				//because some listeners needs origin one
486. 				//we cannot call exit on unexpected child
487. 				context.exit(labeledStatement);
488. 				//use childStmt instead of helper block
489. 				CtElement parent = block.getParent();
490. 				//remember whether parent was implicit
491. 				boolean parentIsImplicit = parent.isImplicit();
492. 				//because replace resets CtBlock#isImplicit to false
493. 				block.replace(childStmt);
494. 				//but we need to keep it as it was before
495. 				parent.setImplicit(parentIsImplicit);
496. 				return;
497. 			}
498. 		}
499. 		//else example code:
500. 		//label:;
501. 		//label1: label2: while(true);
502. 		//needs to keep an implicit helper CtBlock as holder of `label1`
503. 		context.exit(labeledStatement);
504. 	}
