815. 	static CompilationUnit getOrCreateCompilationUnit(CompilationUnitDeclaration compilationUnitDeclaration, Factory factory) {
816. 		CompilationUnit compilationUnitSpoon = factory.CompilationUnit().getOrCreate(new String(compilationUnitDeclaration.getFileName()));
817. 		if (compilationUnitSpoon.getLineSeparatorPositions() == null) {
818. 			compilationUnitSpoon.setLineSeparatorPositions(compilationUnitDeclaration.compilationResult.lineSeparatorPositions);
819. 		} else if (compilationUnitSpoon.getLineSeparatorPositions() != compilationUnitDeclaration.compilationResult.lineSeparatorPositions) {
820. 			throw new SpoonException("Unexpected CompilationUnit lineSeparatorPositions");
821. 		}
822. 		return compilationUnitSpoon;
823. 	}
