825. 	@Override
826. 	public boolean visit(CompilationUnitDeclaration compilationUnitDeclaration, CompilationUnitScope scope) {
827. 		context.compilationunitdeclaration = scope.referenceContext;
828. 		context.compilationUnitSpoon = getOrCreateCompilationUnit(context.compilationunitdeclaration, getFactory());
829. 		ModuleBinding enclosingModule = scope.fPackage.enclosingModule;
830. 
831. 		CtModule module;
832. 		if (!enclosingModule.isUnnamed() && enclosingModule.shortReadableName() != null && enclosingModule.shortReadableName().length > 0) {
833. 			module = getFactory().Module().getOrCreate(String.valueOf(enclosingModule.shortReadableName()));
834. 		} else {
835. 			module = getFactory().Module().getUnnamedModule();
836. 		}
837. 
838. 		context.compilationUnitSpoon.setDeclaredPackage(getFactory().Package().getOrCreate(CharOperation.toString(scope.currentPackageName), module));
839. 		CtPackageDeclaration packageDeclaration = context.compilationUnitSpoon.getPackageDeclaration();
840. 		if (packageDeclaration != null) {
841. 			ImportReference packageRef = compilationUnitDeclaration.currentPackage;
842. 			if (packageRef != null) {
843. 				char[] content = context.getCompilationUnitContents();
844. 				int declStart = packageRef.declarationSourceStart;
845. 				//look for first comment
846. 				int firstComment = PositionBuilder.findNextNonWhitespace(false, content, packageRef.sourceStart(), 0);
847. 				if (firstComment < packageRef.sourceStart() && content[firstComment] == '/' && content[firstComment + 1] == '*') {
848. 					//there is a `/*` or `/**`comment before package reference;
849. 					//such comment is understood as compilation unit comment
850. 					//all next comments belong to package declaration
851. 					int commentEnd = PositionBuilder.getEndOfComment(content, packageRef.sourceStart(), firstComment);
852. 					declStart = PositionBuilder.findNextNonWhitespace(false, content, packageRef.sourceStart(), commentEnd + 1);
853. 				} else {
854. 					declStart = firstComment;
855. 				}
856. 				packageDeclaration.setPosition(factory.Core().createCompoundSourcePosition(
857. 						context.compilationUnitSpoon, packageRef.sourceStart(), packageRef.sourceEnd(), declStart, packageRef.declarationEnd, context.compilationUnitSpoon.getLineSeparatorPositions()));
858. 				packageDeclaration.getReference().setPosition(factory.Core().createSourcePosition(context.compilationUnitSpoon, packageRef.sourceStart(), packageRef.sourceEnd(), context.compilationUnitSpoon.getLineSeparatorPositions()));
859. 			}
860. 		}
861. 		return true;
862. 	}
