1146. 		if (!methodDeclaration.isAbstract() && (methodDeclaration.modifiers & ClassFileConstants.AccNative) == 0) {
1147. 			context.enter(getFactory().Core().createBlock(), methodDeclaration);
1148. 			context.exit(methodDeclaration);
