1443. 		inv.setExecutable(references.getExecutableReference(messageSend));
1444. 		if (messageSend.binding instanceof ProblemMethodBinding) {
1445. 			// We are in a static complex in noclasspath mode.
1446. 			if (inv.getExecutable() != null && inv.getExecutable().getDeclaringType() != null) {
1447. 				inv.setTarget(factory.Code().createTypeAccess(inv.getExecutable().getDeclaringType(), inv.getExecutable().getDeclaringType().isAnonymous()));
1448. 			}
1449. 			if (messageSend.expectedType() != null) {
1450. 				inv.getExecutable().setType(references.getTypeReference(messageSend.expectedType()));
1451. 			}
1452. 		}
1453. 		// No explicit type arguments given for call, but JDT inferred them (e.g. in a List.of("foo") call)
1454. 		if (messageSend.binding instanceof ParameterizedGenericMethodBinding && messageSend.typeArguments == null) {
1455. 			ParameterizedGenericMethodBinding binding = (ParameterizedGenericMethodBinding) messageSend.binding;
1456. 			for (TypeBinding argument : binding.typeArguments) {
1457. 				CtTypeReference<Object> reference = getReferencesBuilder().getTypeReference(argument);
1458. 				reference.setImplicit(true);
1459. 				inv.addActualTypeArgument(reference);
1460. 			}
1461. 		}
1462. 		context.enter(inv, messageSend);
1463. 		return true;
1464. 	}
