1558. 			context.enter(
1559. 					helper.createVariableAccess(
1560. 							factory.Core().createUnboundVariableReference().<CtUnboundVariableReference>setSimpleName(qualifiedNameRef.toString()),
1561. 							isLhsAssignment(context, qualifiedNameRef)),
