151. 	@Override
152. 	public void scanCtElement(CtElement e) {
153. 		if (child instanceof CtAnnotation && this.jdtTreeBuilder.getContextBuilder().annotationValueName.isEmpty()) {
154. 			// we check if the current element can have the annotation attached
155. 			CtAnnotatedElementType annotatedElementType = CtAnnotation.getAnnotatedElementTypeForCtElement(e);
156. 			annotatedElementType = (e instanceof CtTypeParameter || e instanceof CtTypeParameterReference) ? CtAnnotatedElementType.TYPE_USE : annotatedElementType;
157. 
158. 			// in case of noclasspath, we cannot be 100% sure, so we guess it must be attached...
159. 			if (this.jdtTreeBuilder.getFactory().getEnvironment().getNoClasspath() || (annotatedElementType != null && JDTTreeBuilderQuery.hasAnnotationWithType((Annotation) childJDT, annotatedElementType))) {
160. 				e.addAnnotation((CtAnnotation<?>) child);
161. 			}
162. 
163. 			// in this case the annotation should be (also) attached to the type
164. 			if (e instanceof CtTypedElement && JDTTreeBuilderQuery.hasAnnotationWithType((Annotation) childJDT, CtAnnotatedElementType.TYPE_USE)) {
165. 				List<CtAnnotation> annotations = new ArrayList<>();
166. 				if (!annotationsMap.containsKey(e)) {
167. 					annotationsMap.put((CtTypedElement<?>) e, annotations);
168. 				} else {
169. 					annotations = annotationsMap.get(e);
170. 				}
171. 				annotations.add((CtAnnotation) child.clone());
172. 				annotationsMap.put((CtTypedElement<?>) e, annotations);
173. 			}
174. 		}
175. 	}
176. 
177. 	private void substituteAnnotation(CtTypedElement ele) {
178. 		if (annotationsMap.containsKey(ele)) {
179. 			List<CtAnnotation> annotations = annotationsMap.get(ele);
180. 			for (CtAnnotation annotation : annotations) {
181. 
182. 				// in case of noclasspath we attached previously the element:
183. 				// if we are here, we may have find an element for whom it's a better place
184. 				if (this.jdtTreeBuilder.getFactory().getEnvironment().getNoClasspath() && annotation.isParentInitialized()) {
185. 					CtElement parent = annotation.getParent();
186. 					parent.removeAnnotation(annotation);
187. 				}
188. 
189. 				if (!ele.getType().getAnnotations().contains(annotation)) {
190. 					ele.getType().addAnnotation(annotation.clone());
191. 				}
192. 			}
193. 			annotationsMap.remove(ele);
194. 		}
195. 	}
