199. 		if (child instanceof CtTypeAccess) {
200. 			e.addThrownType(((CtTypeAccess) child).getAccessedType());
201. 			return;
202. 		} else if (child instanceof CtParameter) {
203. 			e.addParameter((CtParameter<?>) child);
204. 			return;
205. 		} else if (child instanceof CtBlock && !(e instanceof CtMethod || e instanceof CtConstructor)) {
206. 			e.setBody((CtBlock<R>) child);
207. 			return;
208. 		} else if (child instanceof CtReceiverParameter ctReceiverParameter) {
209. 			e.setReceiverParameter(ctReceiverParameter);
210. 		}
211. 		super.scanCtExecutable(e);
212. 	}
