225. 			if (!(this.child instanceof CtBlock)) {
226. 				child = jdtTreeBuilder.getFactory().Code().createCtBlock(child);
227. 				child.setImplicit(true);
228. 				child.setPosition(this.child.getPosition());
229. 			}
230. 			loop.setBody(child);
231. 		}
232. 		super.scanCtLoop(loop);
233. 	}
