275. 	@Override
276. 	public <T> void scanCtVariable(CtVariable<T> v) {
277. 		System.out.println("DEBUG scanCtVariable: v=" + v.getSimpleName() + " child=" + child.getClass().getName() + " childJDT=" + (childJDT == null ? "null" : childJDT.getClass().getName()));
278. 		if (childJDT instanceof TypeReference && child instanceof CtTypeAccess) {
279. 			v.setType(((CtTypeAccess) child).getAccessedType());
280. 			substituteAnnotation((CtTypedElement) v);
281. 			return;
282. 		} else if (child instanceof CtExpression) {
283. 			System.out.println("DEBUG scanCtVariable: child is CtExpression. hasChildEqualsToDefaultValue(v)=" + hasChildEqualsToDefaultValue(v));
284. 			if (hasChildEqualsToDefaultValue(v)) {
285. 				v.setDefaultExpression((CtExpression<T>) child);
286. 				return;
287. 			}
288. 		}
289. 		super.scanCtVariable(v);
290. 	}
