292. 	private <T> boolean hasChildEqualsToDefaultValue(CtVariable<T> ctVariable) {
293. 		if (jdtTreeBuilder.getContextBuilder().getCurrentNode() instanceof AnnotationMethodDeclaration) {
294. 			final AnnotationMethodDeclaration parent = (AnnotationMethodDeclaration) jdtTreeBuilder.getContextBuilder().getCurrentNode();
295. 			// Default value is equals to the jdt child.
296. 			return parent.defaultValue != null && getFinalExpressionFromCast(parent.defaultValue).equals(childJDT)
297. 					// Return type not yet initialized.
298. 					&& !child.equals(ctVariable.getDefaultExpression());
299. 		}
300. 		final AbstractVariableDeclaration parent = (AbstractVariableDeclaration) jdtTreeBuilder.getContextBuilder().getCurrentNode();
301. 		// Default value is equals to the jdt child.
302. 		System.out.println("DEBUG hasChildEqualsToDefaultValue: parent.initialization=" + (parent.initialization == null ? "null" : parent.initialization.getClass().getName()));
303. 		if (parent.initialization != null) {
304. 			System.out.println("DEBUG hasChildEqualsToDefaultValue: parent.initialization == childJDT: " + (getFinalExpressionFromCast(parent.initialization) == childJDT));
305. 			System.out.println("DEBUG hasChildEqualsToDefaultValue: parent.initialization.equals(childJDT): " + getFinalExpressionFromCast(parent.initialization).equals(childJDT));
306. 		}
307. 		return parent.initialization != null && getFinalExpressionFromCast(parent.initialization).equals(childJDT)
308. 				// Return type not yet initialized.
309. 				&& !child.equals(ctVariable.getDefaultExpression());
310. 	}
311. 
312. 	@Override
313. 	public <A extends java.lang.annotation.Annotation> void visitCtAnnotation(CtAnnotation<A> annotation) {
314. 		if (child instanceof CtExpression) {
315. 			annotation.addValue(this.jdtTreeBuilder.getContextBuilder().annotationValueName.peek(), child);
316. 		}
317. 		super.visitCtAnnotation(annotation);
318. 	}
