437. 	@Override
438. 	public <T> void visitCtBinaryOperator(CtBinaryOperator<T> operator) {
439. 		CtElement child = operator.getKind() == INSTANCEOF && operator.getLeftHandOperand() != null
440. 			? adjustIfLocalVariableToTypePattern(this.child)
441. 			: this.child;
442. 		if (child instanceof CtExpression) {
443. 			if (operator.getLeftHandOperand() == null) {
