448. 					int childEnd = child.getPosition().getSourceEnd();
449. 					SourcePosition oldPos = operator.getPosition();
450. 					if (oldPos.isValidPosition() && oldPos.getSourceEnd() < childEnd) {
451. 						//fix parent position if right hand expression is `x instanceof List<?>` which has bad sourceEnd ending before `<?>
452. 						int[] lineSeparatorPositions = jdtTreeBuilder.getContextBuilder().getCompilationUnitLineSeparatorPositions();
453. 						operator.setPosition(operator.getFactory().Core().createSourcePosition(
454. 								oldPos.getCompilationUnit(),
455. 								oldPos.getSourceStart(), childEnd,
456. 								lineSeparatorPositions));
457. 					}
458. 				}
459. 				operator.setRightHandOperand((CtExpression<?>) child);
460. 				return;
461. 			} else if (jdtTreeBuilder.getContextBuilder().getCurrentNode() instanceof StringLiteralConcatenation) {
462. 				CtBinaryOperator<?> op = operator.getFactory().Core().createBinaryOperator();
463. 				op.setKind(BinaryOperatorKind.PLUS);
464. 				op.setLeftHandOperand(operator.getLeftHandOperand());
465. 				op.setRightHandOperand(operator.getRightHandOperand());
466. 				op.setType(operator.getFactory().Type().stringType());
467. 				operator.setLeftHandOperand(op);
468. 				operator.setRightHandOperand(((CtExpression<?>) child));
469. 				int[] lineSeparatorPositions = jdtTreeBuilder.getContextBuilder().getCompilationUnitLineSeparatorPositions();
470. 				SourcePosition leftPosition = op.getLeftHandOperand().getPosition();
471. 				SourcePosition rightPosition = op.getRightHandOperand().getPosition();
472. 				op.setPosition(op.getFactory().createSourcePosition(leftPosition.getCompilationUnit(), leftPosition.getSourceStart(), rightPosition.getSourceEnd(), lineSeparatorPositions));
473. 				return;
474. 			}
475. 		}
476. 		super.visitCtBinaryOperator(operator);
477. 	}
