490. 			typePattern.setVariable((CtLocalVariable<?>) child);
491. 			// as we create the type pattern just here, we need to set its source position - which is luckily the same
492. 			typePattern.setPosition(child.getPosition());
493. 			child = typePattern; // replace the local variable with a pattern (which is a CtExpression)
494. 		}
495. 		return child;
496. 	}
