515. 		if (node instanceof CaseStatement) {
516. 			caseStatement.setCaseKind(((CaseStatement) node).isSwitchRule ? CaseKind.ARROW : CaseKind.COLON);
517. 		}
518. 		if (shouldAddAsCaseExpression(caseStatement, node)) {
519. 			if (child instanceof CtPattern pattern) {
520. 				caseStatement.addCaseExpression((CtExpression<E>) jdtTreeBuilder.getFactory().Core().createCasePattern().setPattern(pattern));
521. 			} else {
