523. 			}
524. 			return;
525. 		} else if (child instanceof CtStatement) {
526. 			caseStatement.addStatement((CtStatement) child);
527. 			return;
528. 		} else if (child instanceof CtExpression<?> guard) {
529. 			caseStatement.setGuard(guard);
530. 		}
531. 		super.visitCtCase(caseStatement);
