534. 	private <E> boolean shouldAddAsCaseExpression(CtCase<E> caseStatement, ASTNode node) {
535. 		if (!(node instanceof CaseStatement cs)) {
536. 			return false;
537. 		}
538. 		if (cs.constantExpressions == null) {
539. 			return false;
540. 		}
541. 		if (child instanceof CtExpression
542. 			&& caseStatement.getCaseExpressions().size() < cs.constantExpressions.length) {
543. 			return true;
544. 		}
545. 		// case A _, B _ -> {} is only one constantExpression in JDT, but an EitherOrMultiPattern
546. 		// so we need to unpack it and see how many case expressions it actually is
547. 		if (cs.constantExpressions.length == 1 && cs.constantExpressions[0] instanceof EitherOrMultiPattern eomp) {
548. 			// returns true if we still expect more case expressions to be added
549. 			return caseStatement.getCaseExpressions().size() < eomp.getAlternatives().length;
550. 		}
551. 		return false;
552. 	}
