600. 	private <T> void fixJdtEnumConstructorSuperCall(CtClass<T> ctClass, CtConstructor<T> constructor) {
601. 		// For some reason JDT inserts a `super()` call in implicit enum constructors.
602. 		// Explicit super calls are forbidden as java.lang.Enum subclasses are permitted by the JLS to delegate
603. 		// to the Enum constructor in whatever way they like.
604. 		// The constructor is implicit so this isn't *technically* illegal, but it doesn't really make much sense
605. 		// as explicit constructors can never contain such a call. Additionally, the Enum class from the standard
606. 		// library has a "String, int" constructor, rendering the parameterless supercall semantically invalid.
607. 		// We just remove the call to make it a bit more consistent.
608. 		// See https://github.com/INRIA/spoon/issues/4758 for more details.
609. 		if (!child.isImplicit() || !ctClass.isEnum() || !constructor.getParameters().isEmpty()) {
610. 			return;
611. 		}
612. 		if (constructor.getBody().getStatements().isEmpty()) {
613. 			return;
614. 		}
615. 		if (!(constructor.getBody().getStatement(0) instanceof CtInvocation)) {
616. 			return;
617. 		}
618. 
619. 		CtInvocation<?> superCall = constructor.getBody().getStatement(0);
620. 		if (superCall.getExecutable().getSimpleName().equals("<init>")) {
621. 			constructor.getBody().removeStatement(superCall);
622. 		}
623. 	}
