792. 						} else {
793. 							invocation.setTarget((CtThisAccess<?>) child);
794. 						}
795. 					}
796. 				} else {
797. 					invocation.setTarget((CtExpression<?>) child);
798. 				}
799. 			} else {
800. 				invocation.addArgument((CtExpression<?>) child);
