807. 	private <T> boolean setTargetFromUnqualifiedAccess(CtInvocation<T> invocation) {
808. 		// A call to a statically imported method (e.g. assertTrue(false)) is modelled as
809. 		// "this.assertTrue(false)" by JDT. We need to unscramble that heuristically and replace the
810. 		// "this" reference with the correct type (e.g. org.junit.api.Assertions)
811. 
812. 		// Additionally, references to methods of enclosing classes are also modelled as "this" by JDT.
813. 		// Compare with Test "correctlySetsThisTargetForUnqualifiedCalls".
814. 
815. 		// We need a MessageSend as the parent to resolve the actualType from the receiver
816. 		if (!(parentPair.node() instanceof MessageSend messageSend)) {
817. 			return false;
818. 		}
819. 		if (messageSend.actualReceiverType == null || messageSend.receiver.resolvedType == null) {
820. 			return false;
821. 		}
822. 
823. 		ReferenceBuilder referenceBuilder = jdtTreeBuilder.getReferencesBuilder();
824. 		CtTypeReference<?> actualReceiverType = referenceBuilder.getTypeReference(messageSend.actualReceiverType);
825. 		CtTypeReference<?> resolvedReceiverType = referenceBuilder.getTypeReference(messageSend.receiver.resolvedType);
826. 
827. 		// If they match we have a normal "this" reference
828. 		if (actualReceiverType.equals(resolvedReceiverType)) {
829. 			return false;
830. 		}
831. 
832. 		if (messageSend.binding() == null || !messageSend.binding().isStatic()) {
833. 			// Emulate outer this access
834. 			while (resolvedReceiverType != null) {
835. 				resolvedReceiverType = resolvedReceiverType.getDeclaringType();
836. 				if (actualReceiverType.equals(resolvedReceiverType)) {
837. 					invocation.setTarget(jdtTreeBuilder.getFactory().Code().createThisAccess(actualReceiverType, true));
838. 					return true;
839. 				}
840. 			}
841. 			// I don't think this can happen but let's be conservative and preserve the previous behaviour
842. 			return false;
843. 		}
844. 
845. 		// If not, we probably had a static import/static outer method reference here and should use the actual type
846. 		// instead
847. 		invocation.setTarget(jdtTreeBuilder.getFactory().Code().createTypeAccess(actualReceiverType, true));
848. 		return true;
849. 	}
