851. 	private <T> boolean hasChildEqualsToQualification(CtInvocation<T> ctInvocation) {
852. 		if (!(jdtTreeBuilder.getContextBuilder().getCurrentNode() instanceof ExplicitConstructorCall)) {
853. 			return false;
854. 		}
855. 		final ExplicitConstructorCall parent = (ExplicitConstructorCall) jdtTreeBuilder.getContextBuilder().getCurrentNode();
856. 		// qualification is equals to the jdt child.
857. 		return parent.qualification != null && getFinalExpressionFromCast(parent.qualification).equals(childJDT)
858. 				// qualification not yet initialized.
859. 				&& !child.equals(ctInvocation.getTarget());
860. 	}
