950. 	@Override
951. 	public <T> void visitCtNewClass(CtNewClass<T> newClass) {
952. 		if (child instanceof CtClass) {
953. 			newClass.setAnonymousClass((CtClass<?>) child);
954. 			final QualifiedAllocationExpression node = (QualifiedAllocationExpression) jdtTreeBuilder.getContextBuilder().getCurrentNode();
955. 			final ReferenceBinding[] referenceBindings = node.resolvedType == null ? null : node.resolvedType.superInterfaces();
956. 			if (referenceBindings != null && referenceBindings.length > 0) {
957. 				//the interface of anonymous class is not printed so it must have no position
958. 				//note: the interface is sometimes already assigned so call setSuperInterfaces to replace it
959. 				((CtClass<?>) child).setSuperInterfaces(Collections.singleton(cloneAsImplicit(newClass.getType())));
960. 			} else if (newClass.getType() != null) {
