1193. 	/**
1194. 	 * Modifies the set of constructors of a {@link CtRecord} instance based on the properties of a new constructor.
1195. 	 * <p>
1196. 	 * This method performs the following operations:
1197. 	 * <p>
1198. 	 * - If the new constructor is implicit, the method checks against all constructors in the record. If a constructor
1199. 	 * with matching parameters is found, the function returns without adding the new constructor.
1200. 	 * <p>
1201. 	 * - If the new constructor is not implicit, the method traverses the existing constructors of the record. If any
1202. 	 * implicit constructor with matching parameters is found, it's removed from the record.
1203. 	 * <p>
1204. 	 * - If constructor to be added passes the conditions above, or no matching parameters are found, it gets added to the record.
1205. 	 *
1206. 	 * @param recordType     The {@link CtRecord} instance to which the new constructor might be added.
1207. 	 * @param newConstructor The new constructor that should be added to the record, contingent on certain conditions.
1208. 	 */
1209. 	private static void adjustConstructors(CtRecord recordType, CtConstructor<Object> newConstructor) {
1210. 		if (newConstructor.isImplicit()) {
1211. 			for (CtConstructor<Object> constructor : recordType.getConstructors()) {
1212. 				if (hasSameParameters(newConstructor, constructor)) {
1213. 					return;
1214. 				}
1215. 			}
1216. 		} else {
1217. 			for (CtConstructor<Object> constructor : recordType.getConstructors()) {
1218. 				if (constructor.isImplicit() && hasSameParameters(newConstructor, constructor)) {
1219. 					recordType.removeConstructor(constructor);
1220. 				}
1221. 			}
1222. 		}
1223. 		recordType.addConstructor(newConstructor);
1224. 	}
1225. 
1226. 	private static boolean hasSameParameters(CtConstructor<Object> newConstructor, CtConstructor<Object> constructor) {
1227. 		// use endsWith because constructor already has a declaring type set while newConstructor doesn't
1228. 		// but we are only interested in the parameters, so we compare e.g. "R(int)" with "(int)"
1229. 		return constructor.getSignature().endsWith(newConstructor.getSignature());
1230. 	}
