 		}
 		for (Statement increment : parent.increments) {
 			if (increment != null && increment.equals(childJDT)) {
 				return true;
 			}
 		}
 		return false;
 	}

 	private boolean isContainedInForCondition() {
 		if (!(jdtTreeBuilder.getContextBuilder().getCurrentNode() instanceof ForStatement)) {
